import type { InterviewQuestion } from '../questions';
import { expandedLessons } from '../content/aws-compute/catalog';

type Draft={lesson:string;topic:string;prompt:string;scenario:string;assumptions:string[];answer:string;hinge:string;rubric:string[];mistake:string;level:1|2|3|4|5;kind:string};
const q=(lesson:string,topic:string,prompt:string,scenario:string,assumptions:string[],answer:string,hinge:string,rubric:string[],mistake:string,level:1|2|3|4|5,kind:string):Draft=>({lesson,topic,prompt,scenario,assumptions,answer,hinge,rubric,mistake,level,kind});

// Individual interview-style prompts. These are original practice scenarios, not reported interview questions.
const drafts:Draft[]=[
q('ec2-model','Nitro and ownership','A team says Nitro means AWS manages its Linux host. Correct the claim and map who owns each layer.','A production EC2 web tier uses an Amazon Linux AMI and a custom systemd service.',['The instance uses a conventional virtual machine, not a managed container runtime.'], 'Nitro provides the underlying virtualization and hardware-backed infrastructure path, while EC2 manages the physical host and instance service. The customer still owns guest patching, OS users, firewall, application packages, instance role, logs, and recovery design. I would document host-level responsibilities separately from workload responsibilities and verify whether any managed service can remove duties the team does not need to own.','A modern hypervisor does not turn IaaS into a managed guest OS.',['Separates AWS host from customer guest responsibilities','Names concrete Linux and application duties','Connects ownership to a service-choice alternative'],'Treating a hardware platform name as proof that AWS patches the guest OS.',2,'Explain the internals'),
q('ec2-model','Instance status signals','EC2 system checks pass, instance checks pass, but the API returns 500. What does that tell you and where do you look next?','The target is registered in an ALB target group and marked healthy.',['Status and ALB health checks use different layers and probes.'], 'The EC2 checks indicate host/guest reachability at their scope, and the ALB check indicates its configured health endpoint passes. None proves every business operation succeeds. Inspect application error logs, deployment version, dependencies, response codes, target response time, and a trace for the failing request. Verify the health endpoint is not overly shallow. Add a business-level synthetic check if the service needs to detect a dependency failure that a simple process probe misses.','Health is a layered signal; “healthy” only means the configured probe passed.',['Distinguishes EC2 and ALB scopes','Investigates application/dependency evidence','Improves readiness or synthetic coverage'],'Restarting a healthy instance before checking a failing dependency.',3,'Production debugging'),
q('ec2-model','VM or container boundary','A service needs a custom kernel module. Would an ECS task on Fargate satisfy it? Defend the first model you would test.','The module must load into the workload kernel and is not replaceable by a userspace agent.',['The requirement is verified against supported Fargate capabilities.'], 'I would test EC2-backed capacity first because it provides guest operating-system and kernel control. A conventional container shares the host kernel, and Fargate does not expose arbitrary host-kernel administration. Confirm the module, kernel version, instance family, and security needs in a disposable environment. If the actual requirement can be met by a userspace sidecar or managed integration, a container platform may reduce operations; otherwise accept patch and fleet ownership on EC2.','The decisive constraint is kernel control, not whether the artifact is a container.',['Maps requirement to kernel ownership','Tests exact capability and supported alternative','Names operational cost of EC2'],'Choosing Fargate because the application already has a Docker image.',4,'Architecture and service choice'),
q('ec2-model','Instance store durability','A cache node uses instance-store NVMe and is terminated during an AZ event. What data should the design expect to lose?','The cache contents are reconstructable from a durable database.',['The selected instance family has instance-store volumes.'], 'Treat instance-store contents as ephemeral to the instance lifecycle. The node can be replaced, so cache entries must be reconstructable and cache misses must not violate correctness. Keep authoritative data in durable storage, make cache warm-up bounded, and prevent a replacement wave from stampeding the database. Measure restore time and database load after an AZ event. If the data is not reconstructable, instance store alone is not an acceptable persistence layer.','Fast local storage and durable storage solve different failure problems.',['States lifecycle data loss','Keeps the source of truth durable','Plans cache rewarm and stampede controls'],'Assuming instance store behaves like an EBS volume after termination.',3,'Failure recovery'),
q('ec2-model','Status-check replacement policy','An Auto Scaling Group replaces an instance when its EC2 instance check fails. What state and data are at risk, and what should recovery rely on?','The service stores local cache and writes authoritative records to RDS.',['The ASG health policy replaces failed instances automatically.'], 'A replacement has a new instance lifecycle and may not contain the old instance’s local cache or unflushed local data. Ensure authoritative writes are committed to RDS or durable storage before acknowledging requests. Treat cache as disposable, configure the application to rewarm safely, and verify that load balancer deregistration drains requests. Test status-check replacement and inspect whether a system-check failure, guest failure, or application failure caused it; each has a different diagnostic path.','Automatic replacement restores capacity only if application state is externalized or reconstructable.',['Identifies local-state risk','Defines durable-write boundary','Includes drain and failure classification'],'Equating ASG replacement with transparent process migration.',4,'Failure recovery'),

q('ec2-instance-choice','Family selection from evidence','A service has 90% CPU and 25% memory utilization at peak, with stable disk and network metrics. Which experiments would distinguish a size issue from a family issue?','The current fleet uses a general-purpose family at 70% target CPU.',['Representative production traffic can be replayed safely in a test environment.'], 'Compare a larger size in the current family with a compute-optimized candidate using the same AMI, data, concurrency and dependency budgets. Measure throughput per instance, p95/p99, throttling, CPU steal/credits where relevant, memory headroom, EBS/network performance and cost per successful request. Keep enough capacity for an AZ failure. High CPU suggests CPU pressure, but profiling should establish whether work is compute-bound or blocked on locks and dependencies before committing.','Family changes should test the suspected bottleneck while holding other variables stable.',['Proposes controlled comparison','Uses user-facing and resource measures','Includes resilience/cost'],'Scaling out or changing family before confirming CPU is useful work rather than wait.',3,'Numerical engineering'),
q('ec2-instance-choice','CPU credits','A burstable instance meets latency for ten minutes, then p99 rises while arrival rate stays flat. What metric would you inspect and what model change might follow?','The instance family uses CPU credits and load is sustained.',['No deployment occurred during the latency shift.'], 'Inspect CPU credit balance and the instance’s baseline performance alongside CPU utilization and throttling. A short test may consume accumulated surplus credits and hide the sustained limit. Run a longer benchmark that spans the production busy period. If credits drain under normal load, compare a fixed-performance family or distribute sustained work across suitable capacity; evaluate the resulting cost and headroom rather than permanently overprovisioning from one spike.','Burst capacity can mask a steady-state mismatch.',['Names credit balance and baseline','Tests long enough to expose depletion','Evaluates a sustained-capacity alternative'],'Treating ten-minute benchmark results as sustained capacity.',3,'Production debugging'),
q('ec2-instance-choice','Architecture migration','An x86 service could save cost on ARM-based EC2, but it includes native libraries. What gates must pass before changing architecture?','The application is stateless and can be deployed to a canary fleet.',['The AWS instance family and required operating system support the target architecture.'], 'Inventory native packages, agents, language runtimes, container base images, monitoring extensions and vendor licenses. Rebuild artifacts for the target architecture, run correctness and performance tests with representative data, and compare price per successful operation. Check mixed-fleet load balancing, deployment rollback and dependency parity. Start with a canary and compare errors, p99, memory, CPU and cost. Keep the previous architecture deployable until rollback is proven.','CPU architecture is a software compatibility change as well as a compute-price change.',['Audits native dependencies','Compares correct unit economics','Defines canary and rollback'],'Assuming source-language portability means binary portability.',4,'Code and configuration'),
q('ec2-instance-choice','EBS bandwidth ceiling','CPU falls after increasing instance count, but job throughput barely improves. What instance and storage limits would you test?','Each worker reads the same volume-backed dataset.',['The load generator and database are not the bottlenecks.'], 'Check each volume’s IOPS and throughput, queue length and latency, plus the aggregate EBS bandwidth and IOPS limits for the selected instance size. More instances can increase contention on shared storage rather than throughput. Compare local caching, partitioned data, larger volume throughput, or a larger instance with higher EBS bandwidth. Change one factor at a time and compare completed jobs per second and p99 I/O latency.','Scale-out cannot exceed a shared storage ceiling.',['Checks volume and instance limits','Recognizes shared contention','Defines measurable alternatives'],'Adding instances when all workers contend on one EBS volume.',4,'Production debugging'),
q('ec2-instance-choice','Instance network limits','A message processor’s CPU is 30%, but packet retransmits and downstream timeouts rise at higher throughput. What evidence can show a network ceiling?','The application sends many small requests to a remote service.',['Security and route configuration are initially unchanged.'], 'Compare network throughput and packet-per-second metrics against the selected instance’s documented bandwidth capabilities, inspect ENA driver and OS counters, retransmits, connection churn, and downstream latency. Small packets can stress packet rate before raw bytes reach a headline bandwidth value. Check TLS setup and ephemeral port use as well. Test a larger network-capable size or connection reuse under a controlled load, and verify the remote service quota before attributing the limit to EC2.','Network capacity includes packets, connections and quotas, not only bytes per second.',['Uses host and AWS metrics','Checks connection reuse and remote quota','Tests family/size change safely'],'Assuming low CPU rules out an instance networking limit.',4,'Production debugging'),

q('ec2-boot','Launch-template reproducibility','Two instances launched from the same ASG behave differently. Which launch inputs do you compare before inspecting application code?','The group recently changed AMI and user data.',['Template versions and image IDs are available in launch records.'], 'Compare the resolved launch-template version, AMI ID, user-data digest, instance type and architecture, block-device mappings, security groups, subnet/AZ, IAM instance profile, metadata options and bootstrap logs. A mutable template default or “latest” image can create a mixed fleet. Reproduce the failing launch from the exact version, then pin a reviewed version and roll out a canary. Record these values in instance metadata or deployment telemetry for future diagnosis.','The declared template name is not proof that both instances used identical resolved inputs.',['Lists resolved launch settings','Checks boot logs and architecture','Provides pinning/reproduction path'],'Comparing only the ASG name and assuming configuration is identical.',3,'Production debugging'),
q('ec2-boot','User-data idempotency','A bootstrap script appends a repository entry and creates a user. It runs twice after an interrupted boot. What can break and how would you make it safe?','The image uses cloud-init and startup may be retried during recovery.',['Bootstrap actions are intended to converge host configuration.'], 'Repeated appends can duplicate repository definitions; user creation may fail or alter an existing account; partial package installation can leave an inconsistent state. Make actions declarative or check-before-create, use strict error handling, and log each step. Prefer baking stable dependencies into an AMI and limit user data to environment-specific configuration. Test interruption after each step. Do not hide errors with `|| true` unless the ignored condition is explicitly safe and observable.','Bootstrap should converge to a known state after partial execution.',['Names at least two repeat-run hazards','Makes setup idempotent and observable','Proposes AMI baking and interruption test'],'Assuming user data always runs exactly once to completion.',3,'Code and configuration'),
q('ec2-boot','Readiness versus running','An instance is `running` but fails ALB health for 80 seconds while downloading a model. How should the launch and health path change?','The model is required before the service can respond correctly.',['Model download duration is variable and must be measured.'], 'Keep the target out of service until the model is ready. Measure cold boot and download distributions, then set ASG health grace and instance warmup with margin. Consider baking the model into an AMI or storing it in a nearby durable source if image size and release process allow. Expose a readiness endpoint that stays false until initialization completes, and monitor startup failures. A long grace period should not turn a permanently broken bootstrap into invisible capacity loss.','EC2 lifecycle state is not application readiness.',['Separates running from ready','Chooses measured warmup/readiness','Considers AMI and observability'],'Returning healthy before the required model is loaded.',3,'Explain the internals'),
q('ec2-boot','IMDSv2 and SSRF','A web application can make arbitrary HTTP requests. Why should you review instance metadata settings, even if the instance role is least privilege?','The application may be vulnerable to server-side request forgery.',['The workload uses an EC2 instance profile.'], 'An SSRF path may reach the instance metadata endpoint and request role credentials. Require IMDSv2 where compatible, set an appropriate hop limit, avoid exposing metadata through proxies or container paths, and scope the instance role to only the host’s required actions. Patch the application and test the exact request path. IMDSv2 reduces certain access paths but does not replace least privilege or SSRF defenses. Rotate or revoke credentials if evidence shows exposure.','Network reachability to metadata can turn an application bug into cloud credential access.',['Explains SSRF-to-credential path','Combines metadata controls with least privilege','Plans compatibility test and response'],'Assuming a private subnet prevents a local SSRF request to metadata.',4,'Security review'),
q('ec2-boot','AMI patch cadence','A team bakes an AMI quarterly but has no emergency patch path. What would you change without returning to untracked manual patching?','Instances are in an Auto Scaling Group behind an ALB.',['Fleet replacement is supported and application state is externalized.'], 'Keep immutable AMI as the normal path but add an expedited image pipeline for critical patches: rebuild, scan, boot-test, run application checks, publish a new version, then replace a canary portion and roll forward. For urgent mitigation, use Systems Manager patch operations with explicit targets, audit output and a plan to return to a known image. Track AMI age and patch SLA. Verify rollback image availability and fleet capacity during replacement.','Immutable images and emergency patch management can be complementary controls.',['Defines fast tested image pipeline','Includes audited break-glass mitigation','Measures patch age and rollback capacity'],'Waiting for the quarterly bake or manually patching without tracking drift.',4,'Architecture and service choice'),
q('ec2-ebs','IOPS and throughput math','A volume performs 6,000 random 8 KiB reads per second. Estimate payload throughput and explain which configured limit may bind.','Ignore protocol overhead for the first calculation.',['The volume and instance must both support the resulting throughput.'], 'Payload rate is 6,000 × 8 KiB = 48,000 KiB/s, approximately 46.9 MiB/s. The workload may bind on IOPS even though byte throughput is modest. Check the volume’s provisioned IOPS, throughput, queue depth and latency, plus instance aggregate EBS limits. Repeat the calculation with the real I/O-size distribution because mixed reads and writes change service behavior. Use CloudWatch and guest metrics to confirm rather than sizing from the arithmetic alone.','IOPS and MiB/s constrain different request patterns.',['Calculates about 47 MiB/s','Identifies IOPS as likely bound','Checks volume and instance caps'],'Comparing IOPS directly with throughput without multiplying by request size.',3,'Numerical engineering'),
q('ec2-ebs','gp3 performance choice','A database has high queue depth and 99th-percentile read latency. How would you decide whether to change gp3 IOPS, throughput, instance size, or query behavior?','Storage metrics are available at one-minute granularity.',['No data-loss event or database failover is in progress.'], 'Correlate volume read/write latency, queue length and throughput with database wait events, query plan and instance EBS bandwidth. If IOPS is saturated while throughput is below limit, provision IOPS; if large I/O reaches bandwidth first, provision throughput or change request pattern. If the instance’s aggregate EBS limit binds, a larger instance may be needed. If one query causes random reads, index or cache changes may be better. Change one layer, replay representative load, and compare p99 plus cost.','The smallest saturated layer determines which setting can help.',['Uses volume, instance and database evidence','Distinguishes IOPS from throughput','Tests query alternative and cost'],'Increasing gp3 throughput when database query behavior is the bottleneck.',4,'Production debugging'),
q('ec2-ebs','Snapshot restore test','A team snapshots a volume nightly and claims a 15-minute RTO. What must be proven before accepting that claim?','The snapshot is in the same Region and a new volume must be created after failure.',['The application needs a consistent database state.'], 'Measure the complete restore path: select the correct recovery point, create and attach volume, initialize or hydrate blocks needed by the workload, mount safely, run database recovery, validate consistency, restore network and application service, and route traffic. Snapshot completion alone does not prove a usable database in 15 minutes. Coordinate multi-volume snapshots and database-native backup semantics as needed. Run timed restore drills and record the actual RTO and data-loss point; improve the process or choose a faster recovery design if it misses target.','RTO covers service recovery, not the snapshot API call.',['Enumerates full restore path','Addresses consistency and initialization','Requires timed drill and measured RPO/RTO'],'Using snapshot creation duration as the entire recovery estimate.',4,'Failure recovery'),
q('ec2-ebs','Filesystem full incident','A service reports ENOSPC although the EBS volume has free bytes in CloudWatch. What guest-level conditions can explain this?','CloudWatch reports volume capacity but not every filesystem allocation detail.',['The EBS volume is attached and status checks pass.'], 'Check filesystem free blocks and inodes separately, partition and filesystem size after volume growth, deleted-but-open files, reserved blocks, container overlay usage, log rotation, and mount points. EBS volume size can exceed the guest partition/filesystem size until expanded. Confirm the service writes to the expected mount rather than the root filesystem. Preserve logs and service state before cleanup; remove or rotate files through the application’s safe procedure, then update monitoring to alert on filesystem and inode utilization.','Cloud volume bytes and guest filesystem capacity are separate layers.',['Checks blocks, inodes, mount and filesystem expansion','Finds deleted-open files and overlays','Fixes monitoring and safe cleanup'],'Increasing EBS size without growing the guest partition and filesystem.',3,'Production debugging'),
q('ec2-ebs','Snapshot consistency boundary','A database uses separate EBS volumes for data and WAL. How do you create a recovery point that preserves their relationship?','The database supports a documented backup/quiesce procedure.',['Writes may be active while backup starts.'], 'Use the database’s supported backup method to establish a consistent checkpoint or quiesce writes, then snapshot the required volumes as a coordinated set. Record database log position and snapshot identifiers. Restore the set into isolation, allow database recovery, and run integrity checks before calling it valid. If application consistency is not required, document crash-consistent recovery assumptions and test replay duration. A set of independently timed snapshots can represent incompatible moments.','Multiple block devices may need a coordinated point in time.',['Coordinates database and volume snapshots','Stores recovery metadata','Tests actual restored consistency'],'Assuming individually successful snapshots form one atomic database backup.',4,'Failure recovery'),

q('ec2-network','Return-path routing','An instance sends SYN packets to a remote subnet, but no connection establishes. How do you test a missing return route?','The destination route is managed by another team.',['VPC Flow Logs can be enabled on both sides.'], 'Inspect the source subnet route and any transit appliance, then inspect the destination subnet route back to the source CIDR. Check peering/TGW route-table association and propagation on both sides, security groups, NACL ingress and ephemeral return ports. Use Reachability Analyzer for the configured path and Flow Logs on each VPC to see whether SYN and response traffic is accepted. A one-way route commonly appears as a timeout rather than a clear refusal. Coordinate route ownership and test from both source and destination.','TCP needs a viable return path; forward routing alone is insufficient.',['Checks both route directions','Distinguishes stateful SG from stateless NACL','Uses flow evidence across ownership boundary'],'Opening inbound security group rules before checking return routing.',3,'Production debugging'),
q('ec2-network','Stateful and stateless rules','A security group allows outbound HTTPS, but a custom NACL blocks high-numbered ports. Why can responses fail?','The client connects to a public HTTPS endpoint through NAT.',['NACL rules are custom and the client uses ephemeral ports.'], 'Security groups are stateful, so return traffic for an allowed outbound connection is tracked. Network ACLs are stateless; they must allow both the outbound destination port and the return packet’s ephemeral destination port. Inspect subnet NACL rules in both directions, route through NAT, and flow logs. Add the narrow ephemeral range required by the OS/network path rather than opening every port. Test with a connection and verify return packets, not just SYN egress.','Statefulness differs at the security-group and subnet-ACL layers.',['States stateful versus stateless semantics','Identifies ephemeral return port','Proposes narrow rule and evidence'],'Assuming the outbound HTTPS rule automatically makes a stateless NACL allow return traffic.',3,'Explain the internals'),
q('ec2-network','Private subnet egress','A private EC2 worker downloads a public package at boot. What routing design provides egress, and how would an S3 endpoint change the cost path?','The worker has no public IPv4 address.',['The package host is public; the artifact could alternatively be mirrored to S3.'], 'A private subnet commonly routes internet-bound IPv4 traffic through a NAT gateway in a public subnet; that public subnet routes to an internet gateway. Confirm return routing, NACLs, DNS and security-group egress. If the artifact is stored in S3, a gateway endpoint can provide a private S3 route and avoid sending that traffic through NAT, but it does not provide general internet access. Compare NAT hourly/data processing and endpoint costs, and mirror immutable packages to reduce dependency on public repositories during boot.','Service endpoints are scoped private routes, not general-purpose egress.',['Traces private-to-NAT-to-IGW path','Separates S3 endpoint from public egress','Includes boot reliability and cost'],'Adding an S3 endpoint and then removing NAT while boot still calls a public repository.',4,'Architecture and service choice'),
q('ec2-network','ENI address mobility','A stateful service uses one ENI with a stable private address. What failover properties does that provide, and what does it not provide?','The ENI can be detached and attached to a compatible replacement in the same AZ.',['The application state is already durable elsewhere.'], 'An ENI can preserve private addressing and security-group identity when attached to a replacement instance within supported placement constraints, which may help a legacy client that requires a stable address. Failover still needs detection, detach/attach, boot and application readiness; it is not instantaneous process migration. An ENI is AZ-scoped and does not itself provide cross-AZ recovery. Use a load balancer or service discovery where possible, and test address ownership and recovery timing.','Stable addressing reduces client reconfiguration but does not remove failure or state recovery.',['Names supported continuity benefit','States AZ and recovery limits','Compares ALB/service discovery'],'Treating an ENI as a multi-AZ floating IP with preserved process state.',4,'Architecture and service choice'),
q('ec2-network','Overlapping CIDR diagnosis','Two VPCs have overlapping RFC1918 ranges and need private connectivity. Why can ordinary VPC peering fail, and what redesign options exist?','The VPCs are controlled by separate organizations.',['Both sides need routing to some overlapping service ranges.'], 'VPC peering does not support routing between overlapping IPv4 CIDR blocks, so the route table cannot distinguish which identical destination range is intended. Plan non-overlapping CIDRs for new networks, or use an explicit translation/proxy boundary or application-layer connectivity for the narrow services that must communicate. Inventory actual used ranges before designing migration, and account for DNS, security and return paths. Avoid assuming Transit Gateway removes the ambiguity of overlapping addresses.','Routing needs unique destination prefixes; a transit hub cannot infer which overlapping host you mean.',['Explains ambiguous routing','Offers migration or translation options','Includes actual used range inventory'],'Adding a Transit Gateway while leaving overlapping destination prefixes unresolved.',4,'Architecture and service choice'),
q('ec2-network','Source/destination check','An EC2 instance forwards packets for other hosts but traffic is dropped. Which instance setting and network controls do you inspect?','The instance is intended to act as a NAT or routing appliance.',['It is not a managed NAT Gateway.'], 'For a routing appliance, disable the instance source/destination check so it can forward traffic not addressed to or sourced from itself. Then verify IP forwarding in the guest, security groups, subnet route tables pointing to the appliance, return routes, and NACLs. Confirm the instance has adequate throughput and HA replacement design. Disabling the check alone does not configure NAT or make the host resilient; consider a managed NAT Gateway if host control is unnecessary.','The EC2 anti-spoofing check and guest forwarding configuration are separate gates.',['Names source/destination check','Checks guest forwarding and routes','Compares managed NAT and HA'],'Disabling the EC2 check without configuring routes and guest packet forwarding.',4,'Code and configuration'),

q('ec2-operations','Session Manager access','Security asks to remove inbound SSH from an EC2 fleet. What must be true for Session Manager to work, and what audit design do you add?','Instances are in private subnets.',['SSM Agent is installed and can reach the required Systems Manager endpoints.'], 'The instance needs a working SSM Agent, an instance profile with required Systems Manager permissions, and network access to Systems Manager endpoints through NAT or VPC endpoints. Operators need IAM permission scoped to the intended instances and session actions. Configure session logging to a protected CloudWatch Logs or S3 destination and audit start/stop events. Test from a private subnet and document break-glass access. Removing SSH ingress is safe only after confirming fleet enrollment and recovery access.','No inbound port is needed, but the management plane still needs identity, agent and egress.',['Names agent, role, endpoints and operator identity','Adds protected audit logging','Tests break-glass path before closing SSH'],'Removing SSH before confirming that all instances are managed and reachable.',4,'Security review'),
q('ec2-operations','Patch compliance','A fleet has 200 instances and 12 are missing a critical patch. How do you identify, patch and prove coverage?','Instances are tagged by environment and application owner.',['Patch Manager baseline is appropriate for the OS distribution.'], 'Use Systems Manager inventory/compliance to identify the exact 12, validate tags and patch baseline, and choose a maintenance window or emergency ring. Patch a canary, reboot if required, verify application and ALB health, then proceed in batches with spare capacity. Capture command/compliance output and compare instance inventory before and after. Confirm the remaining 188 are compliant or explicitly excepted with owner and expiry. An API call reporting success is not proof that the service recovered.','Patch compliance combines desired policy, execution result and application validation.',['Defines inventory and scoped rollout','Includes reboot/capacity and app health','Records residual exceptions'],'Running a global patch command without environment rings or post-reboot checks.',3,'Code and configuration'),
q('ec2-operations','SSH key compromise','An engineer’s shared SSH key is suspected exposed. What actions contain access and restore auditability?','The key was used by several operators across production hosts.',['The fleet can be managed through SSM or rebuilt from known images.'], 'Revoke the key from authorized users and remove it from hosts or centralized access configuration; inspect authentication logs and command history within retention limits. Rotate any credentials accessible from the hosts, review instance-role activity in CloudTrail, and preserve evidence. Move to individual identity through Session Manager or short-lived certificates, require MFA and least privilege, and log sessions centrally. Rebuild hosts if integrity is uncertain. Do not assume key deletion proves there was no access.','Shared credentials erase attribution and compromise every host that trusts the key.',['Contains credential and host access','Reviews downstream secrets and evidence','Moves to attributable short-lived access'],'Changing the key but ignoring credentials or persistence on potentially accessed hosts.',4,'Security review'),
q('ec2-operations','Fleet deployment rollback','A deployment succeeds on 30% of the fleet, then errors rise. How do you roll back without leaving an unknown mixed version?','The fleet uses an Auto Scaling Group and immutable AMIs.',['The previous launch-template version is still available.'], 'Stop further rollout and route traffic away from unhealthy targets if possible. Roll the ASG launch template to the known version, then replace or explicitly redeploy instances until the fleet converges. Track each instance’s image and application version; do not rely on ASG desired capacity alone. Preserve failed artifacts/logs and use a canary test before restarting rollout. Confirm deployment surge and healthy capacity do not violate AZ headroom. Record any manual changes as drift to reconcile.','Rollback is fleet convergence to a known artifact, not merely changing the template pointer.',['Stops rollout and protects traffic','Tracks actual instance versions','Validates capacity and drift'],'Assuming existing instances are changed when the launch template version is changed.',4,'Progressive interviewer pressure'),
q('ec2-operations','Secrets on hosts','A script writes a database password into `/etc/app.env` on EC2. What controls reduce exposure and support rotation?','The application needs the password at runtime.',['A managed secret service is available in the account.'], 'Avoid embedding credentials in AMIs or user data. Give the instance profile permission to retrieve only the application’s secret, fetch it at runtime over TLS, restrict file ownership and mode if local caching is necessary, and prevent it from appearing in process arguments or logs. Define cache lifetime and rotation behavior, including reconnecting existing database pools. Use secret access logs and alert on unusual reads. A private subnet does not make a plaintext file safe from a compromised process or operator.','Credential protection spans delivery, disk, process and rotation lifetime.',['Uses least-privilege instance identity','Defines file/log/cache controls','Plans rotation and connection refresh'],'Rotating the secret in the secret store while long-lived processes keep stale credentials.',4,'Security review'),
q('ec2-operations','Run Command scope','An operator wants to run a shell command on “all production” hosts. What safeguards do you require before execution?','The command can restart a service and clear a cache.',['Production hosts are tagged, but tag drift is possible.'], 'Resolve and display the exact target instance IDs, environment and owner before execution; use a small canary target set, concurrency/error thresholds and an approved maintenance window. Review command content and IAM permission, capture output to protected logs, set timeout and rollback action, and verify health after execution. Exclude or separately handle stateful nodes. If tags are the only selector, validate them against inventory to prevent accidental fleet-wide impact.','Fleet automation expands the blast radius of a command, even when the command is simple.',['Confirms exact target set','Uses canary/concurrency and timeout','Captures output and verifies service'],'Trusting a broad tag selector without previewing resolved instances.',3,'Security review'),

q('ec2-alb','Health endpoint design','Should an ALB health endpoint fail whenever a downstream database is briefly unavailable? Defend the probe semantics.','The API can serve cached reads but writes require the database.',['The target group health result affects traffic routing.'], 'Separate process liveness from readiness and consider which operations the instance can safely serve during database impairment. If every target marks unhealthy during a shared database outage, the ALB may fail open or leave no healthy destination; it does not act as a dependency circuit breaker. A readiness check should reflect whether routing to that target improves outcomes, while application logic can shed or degrade only affected operations. Add dependency alarms and controlled overload behavior rather than using a deep health endpoint blindly.','A health check changes routing; it should reflect target usefulness, not every dependency symptom.',['Separates liveness and readiness','Explains shared-dependency fail-open risk','Defines degradation and monitoring'],'Making every target unhealthy for a shared dependency and expecting ALB to block all requests.',5,'Architecture and service choice'),
q('ec2-alb','503 diagnosis','ALB returns 503 during scale-out. What target-group and ASG evidence do you align?','The fleet is expected to grow from 4 to 20 instances.',['The listener rule is unchanged.'], 'Check healthy and registered target counts by AZ, ASG desired/pending/in-service capacity, target registration delay, health reason codes, startup logs, health grace period and subnet/instance launch failures. A target can be `running` but not yet registered or healthy. Also inspect whether the target group has no usable targets and whether the ALB’s fail-open state changes behavior. Mitigate with warm baseline capacity or queue/admission if launch time exceeds burst tolerance, then tune from measured boot-to-healthy time.','Desired capacity and routable target capacity are different states.',['Aligns ASG and target-group series','Checks boot and registration delay','Adds pre-scale/queue mitigation'],'Adding a new listener rule without checking healthy target capacity.',4,'Production debugging'),
q('ec2-alb','All targets unhealthy','The ALB health checks fail for every target. Can you rely on it to stop sending requests? Explain the operational implication.','All registered targets are unhealthy in all enabled Availability Zones.',['No custom target-health routing thresholds are configured.'], 'No. ALB target groups can fail open and route to unhealthy targets when all targets are unhealthy. Treat health checks as routing signals, not a guaranteed traffic rejection mechanism. Use an application/gateway overload response, DNS or regional failover policy where appropriate, and preserve a healthy fallback. Verify current target-group health settings because configurable thresholds can change routing behavior. Test the all-unhealthy case; do not infer it from a single-target failure drill.','The no-healthy-target state can still send traffic to targets.',['States fail-open behavior','Adds explicit admission/failover control','Tests all-target failure and config thresholds'],'Using a failing health check as the only circuit breaker.',4,'Failure recovery'),
q('ec2-alb','Deregistration delay','A request normally takes 12 seconds but can take 75 seconds at p99. What should determine ALB deregistration delay and application shutdown?','ASG scale-in or deployment can terminate targets.',['Requests can be drained or safely retried by the client.'], 'Measure the distribution of in-flight request duration and define how the application handles shutdown. Set deregistration delay long enough for expected safe drain, but bounded; stop new work, finish or cancel active requests, flush state and exit before the termination deadline. If retries are possible, ensure the operation is idempotent. Test scale-in while a p99 request is active. A very long delay retains capacity and can slow deployments; a short one interrupts work.','Drain duration must match request semantics and the termination workflow.',['Uses p99/in-flight behavior','Defines app shutdown and idempotency','Tests both availability and capacity cost'],'Setting delay to average duration and ignoring long-tail work.',4,'Numerical engineering'),
q('ec2-alb','Listener routing','A new `/v2/*` listener rule unexpectedly sends `/v2/admin` to the public API target group. What configuration details do you inspect?','Several host/path rules and priorities exist.',['The listener uses HTTPS and forwards to multiple target groups.'], 'Inspect listener rule priority order, host and path conditions, path normalization assumptions, default action and the deployed rule set. A higher-priority broad path may match before a narrower admin rule. Confirm target-group health and security boundaries; routing is not authorization. Add an explicit authentication/authorization check in the service and test representative path variants. Use staged rule deployment and ALB access logs to identify which action matched.','Listener path matching routes traffic but does not authorize the caller.',['Checks ordering and default action','Separates routing from authorization','Adds path tests and access-log evidence'],'Assuming a private or specialized target group makes the endpoint protected.',3,'Production debugging'),

q('ec2-asg','Target tracking calculation','A target is 60% CPU and 10 instances currently average 60%. If load doubles and per-instance work is linear, estimate starting capacity and state why this is not the final desired count.','Current service has stable work per request and no dependency bottleneck.',['CPU is a suitable scaling metric and the fleet can be distributed evenly.'], 'To preserve similar CPU, a first-order estimate is 20 instances: twice the demand requires twice the capacity under linear scaling. Validate request mix, instance warmup, scale-out rate, AZ failure headroom, minimum/maximum capacity and downstream limits. Target tracking adjusts desired capacity from observed metrics; instances still need to launch and pass health checks. If CPU is not proportional to demand or latency, use a better metric such as requests per target or queue age.','The calculation is a baseline only; the scaling signal and readiness delay govern real response.',['Calculates 20','States linearity assumptions','Adds warmup, AZ and dependency checks'],'Treating a target-tracking policy as instantaneous capacity.',3,'Numerical engineering'),
q('ec2-asg','Warmup versus grace period','Explain why an ASG health-check grace period and default instance warmup are not interchangeable.','Instances need 70 seconds to boot and another 50 seconds to reach steady metrics.',['ELB health checks are enabled for the group.'], 'The health-check grace period affects when Auto Scaling considers a newly launched instance unhealthy for replacement. Default instance warmup controls when new capacity’s metrics are included in dynamic scaling policy calculations and related scale behavior. They address different decisions. Measure boot-to-healthy and metric stabilization separately, set both intentionally, and inspect instance refresh behavior. If grace is too short, healthy slow starters churn; if warmup is too long, scale-out reacts slowly to continued demand.','One timer protects health evaluation; another informs feedback control.',['Defines each setting distinctly','Uses separate measurements','Names both too-short and too-long failure modes'],'Copying one value into both settings without measuring their purpose.',4,'Explain the internals'),
q('ec2-asg','Desired versus healthy','Desired capacity rises from 8 to 16, but healthy ALB targets remain at 8 for three minutes. What do you inspect before raising the ASG maximum?','The group launches in two private subnets.',['The max size is already above 16.'], 'Inspect scaling activities and pending instances, EC2 launch errors, quota/capacity availability, subnet IPs, launch-template permissions, user-data duration, EC2 checks, target registration and health reason codes. Raising max size helps only if instances can launch and become ready. If boot dependencies are rate-limited, a larger launch wave can worsen the delay. Identify the blocked transition and fix it; then test burst scale-out from a controlled baseline.','Desired count is a controller target, not proof of capacity creation.',['Traces launch-to-healthy stages','Checks subnet/quota/bootstrap limits','Avoids increasing max as blind fix'],'Increasing maximum capacity when instances fail during launch or health checks.',4,'Production debugging'),
q('ec2-asg','Lifecycle hook deadline','A termination lifecycle hook drains a worker from a queue, but some jobs last 20 minutes. What must the hook and job model guarantee?','The ASG termination lifecycle action has a finite timeout.',['Jobs may be retried from a durable queue after termination.'], 'The hook must complete within its configured lifecycle-action timeout or the instance can proceed to termination according to the action/result. Stop accepting new jobs, checkpoint or safely finish in-flight work, and heartbeat only when progress and remaining deadline justify it. Ensure queue visibility and job leases recover work after forced termination, and make job effects idempotent. If 20-minute work cannot be safely drained inside the deadline, redesign checkpointing or use a compute model/job scheduler suited to long tasks.','Lifecycle hooks delay termination for a bounded period; they do not guarantee indefinite protection.',['States bounded hook and action semantics','Defines checkpoint/redelivery behavior','Compares long-job execution model'],'Assuming a lifecycle hook can keep the instance alive until any job finishes.',4,'Failure recovery'),
q('ec2-asg','Scale-in protection','A stateful consumer is in the middle of a non-checkpointable job when the ASG scales in. Which controls help, and what risk remains?','The job can be retried, but retry has cost.',['The queue retains the message until acknowledged.'], 'Use scale-in protection or lifecycle hooks to avoid abrupt removal while work is active, and stop polling before drain. Persist job progress or make the whole job safely retryable with an idempotency key. Protection can delay scale-in and strand capacity if the process hangs, so include a deadline and operator recovery path. Ensure queue visibility covers work and extends safely when needed. A protection flag alone does not make in-memory progress durable.','The control delays removal; only durable checkpoints or idempotency protect work from failure.',['Combines termination controls with durable job design','Mentions scale-in cost and deadline','Covers queue visibility and recovery'],'Assuming scale-in protection makes a running job immune to host failure.',4,'Failure recovery'),
q('ec2-asg','AZ distribution and capacity','An ASG has desired capacity 12 across three AZs, but one AZ has no available instance capacity. What should happen and what do you verify?','The group spans three AZs with subnet capacity in each.',['The application can run in any of the three AZs.'], 'Auto Scaling can attempt to rebalance or launch in other enabled AZs, but exact distribution depends on capacity, subnet and group configuration. Verify launch failures, AZ distribution, subnet IP availability and whether the group can use alternate instance types or purchase options. Check whether a rebalance temporarily launches surge capacity and whether the max size permits it. Prove surviving two-AZ capacity meets demand. Do not assume desired capacity is evenly available when one AZ cannot launch.','AZ balance is a policy goal constrained by actual capacity and address space.',['Checks activity and subnet constraints','Considers instance-type flexibility and surge','Proves N-1 service capacity'],'Assuming the ASG will always maintain exact balance regardless of AZ capacity.',4,'Architecture and service choice'),

q('ec2-ha','N-1 capacity math','Three AZs each run 8 instances. Peak traffic needs 18 instances and the fleet has a 20% safety margin goal. Is the design N-1 safe?','Traffic is evenly distributable across the surviving AZs.',['Safety margin means 20% above peak required instance count.'], 'After losing one AZ, 16 instances remain. Peak demand with 20% headroom is 18 × 1.2 = 21.6, so the fleet is not N-1 safe. Increase total capacity or improve per-instance throughput, or define a controlled degradation/queueing plan. Also test whether the ALB, ASG, subnets, database and NAT path can handle the surviving-zone load. Capacity count is necessary but not sufficient for AZ resilience.','The surviving capacity is below the explicit peak-plus-headroom requirement.',['Calculates 16 survivors and 21.6 target','Gives viable redesign choices','Checks path dependencies beyond EC2 count'],'Calling 16 survivors safe because they cover the raw 18-instance peak after an incorrect assumption.',4,'Numerical engineering'),
q('ec2-ha','AZ versus Region failure','A product asks for “multi-AZ and multi-Region availability.” What questions determine whether both are required?','Data replication has nonzero lag and the app has regional endpoints.',['The business has not yet set RTO/RPO.'], 'Ask which failure scenarios are in scope, how long service can be unavailable, how much committed data may be lost, and whether write conflicts or data residency constrain recovery. Multi-AZ handles selected AZ failures within a Region; multi-Region requires data replication, global routing, operational failover and consistency decisions. Quantify RTO/RPO per dependency, test failover, and price the standby capacity. Do not add a second Region without a runbook and tested data recovery path.','“High availability” is an objective that needs failure scope and recovery targets.',['Defines AZ and Region scope','Elicits RTO/RPO and consistency','Includes test and operating cost'],'Treating a second Region as automatic failover with zero data loss.',4,'Architecture and service choice'),
q('ec2-ha','Capacity placement dependency','The EC2 fleet is spread across AZs, but all outbound calls use one NAT gateway in AZ A. What resilience and cost questions do you raise?','Workers in AZ B and C route outbound through the AZ A NAT.',['The application depends on outbound SaaS and AWS APIs.'], 'The single NAT path is a dependency on AZ A and may create cross-AZ data charges and latency. If that AZ fails, workers may lose required egress. Consider NAT per AZ with subnet-local routes, or VPC endpoints for AWS services; compare cost, route management and failure behavior. Test an AZ A loss and verify the remaining workers can reach required dependencies. Add per-AZ NAT health and data-processing cost visibility.','Multi-AZ compute cannot compensate for a single-AZ network egress dependency.',['Finds NAT as AZ dependency','Compares per-AZ NAT and endpoints','Includes failure test and cost'],'Counting only application instances when proving AZ resilience.',4,'Progressive interviewer pressure'),
q('ec2-ha','Failover time budget','Database failover takes 5 minutes, but clients retry every second with no jitter. What can happen to the recovered database and how do you change the plan?','Thousands of API clients share the same failure event.',['Retries are currently synchronized.'], 'Synchronized retries can create a thundering herd just as the database recovers, increasing connection pressure and extending outage. Add exponential backoff with jitter, bounded attempts and an overall deadline; use connection-pool limits and circuit breaking. Queue work that can be delayed. Measure failover plus DNS/client reconnection time against RTO, and test load recovery. Do not mark service restored when the database accepts one connection; require stable latency and error rate.','Recovery traffic can become a second overload after the primary failure ends.',['Explains retry herd','Adds bounded jittered recovery','Defines stable recovery criterion'],'Increasing connection limits during failover without controlling synchronized clients.',5,'Production debugging'),
q('ec2-ha','AZ drill acceptance','What evidence would convince you that an AZ failover drill succeeded for an EC2/ALB service?','The service has an explicit p99 objective and queue-age objective.',['One AZ is intentionally removed from serving capacity in a test.'], 'Verify traffic moves to surviving targets, healthy capacity remains above the documented demand plus headroom, p99/error rate stay within degraded-mode objectives, ASG replacement works, and subnet addresses, NAT/endpoints and database paths remain available. Confirm alarms fire and on-call actions are understood. Measure recovery time and backlog drain rate, then restore the AZ and check rebalance behavior. Record gaps and repeat the drill after fixes; a green dashboard without customer-level measures is insufficient.','A drill proves an objective only when user-visible outcome and recovery path are measured.',['Defines user-facing success metrics','Checks surviving dependencies and alarms','Requires repeat after remediation'],'Declaring success because the ASG recreated an instance.',4,'Architecture and service choice'),

q('ec2-troubleshooting','Low CPU, high latency','EC2 CPU is 25%, memory is stable, but API p99 rises from 400 ms to 3 seconds. Give a ranked diagnostic plan.','Latency began after a database release; host count is unchanged.',['Application logs include request IDs and dependency timings.'], 'Compare ALB target response time, application spans, database query latency/locks/connections, EBS waits, network retransmits and thread/connection-pool wait by request ID and deployment time. Low CPU suggests the process may be waiting, not that capacity is sufficient. Check connection exhaustion and downstream retries first because the database release aligns with the change. Mitigate with rollback or traffic shaping if evidence supports it, then verify p99 and error rate. Avoid scaling the EC2 fleet until shared dependency capacity is understood.','A blocked process can be slow with idle CPU.',['Uses timeline and span decomposition','Prioritizes changed dependency evidence','Chooses reversible mitigation and validates'],'Adding EC2 instances because p99 is high despite a shared DB bottleneck.',4,'Production debugging'),
q('ec2-troubleshooting','Status-check failure response','An instance has a failed system status check but the application data is on EBS. What recovery choices and data risks do you compare?','The instance is EBS-backed and uses an Auto Scaling Group.',['No local instance-store data is authoritative.'], 'Inspect the system-check cause and AWS events. For an EBS-backed instance, stop/start may move it to a new host, but the outage and address changes must be considered; ASG replacement may be simpler if the app is stateless and the volume lifecycle is understood. Verify whether the root/data volumes persist or are deleted on termination, and ensure the volume can attach in the required AZ. Preserve logs where possible and avoid destructive recovery before confirming data ownership.','Recovery choice depends on instance backing, volume lifecycle and whether host identity matters.',['Compares stop/start and replacement','Checks EBS AZ and delete-on-termination','Preserves evidence and data'],'Terminating the instance before verifying that required EBS volumes persist.',4,'Failure recovery'),
q('ec2-troubleshooting','ALB 502 versus 504','Users report both 502 and 504 from an ALB. What distinct causes and metrics do you inspect?','The target is an EC2 HTTP service behind an ALB.',['The ALB listener and target group are active.'], 'A 502 can indicate the target closed/reset a connection or returned an invalid response; a 504 points toward the target failing to respond before the load balancer timeout or a connection timeout. Compare ALB access-log error reason, target response time, target health, connection resets, app logs, process restarts and downstream spans. Check protocol/port and keep-alive behavior. Use error-class-specific mitigations; raising timeout can worsen occupied capacity if a dependency is simply slow.','Different gateway errors narrow the failing stage but require logs and timing to confirm.',['Distinguishes likely 502/504 classes','Uses ALB and app evidence','Avoids timeout increase as blind fix'],'Treating all 5xx as one EC2 health problem.',4,'Production debugging'),
q('ec2-troubleshooting','Disk queue diagnosis','An EC2 worker’s job time doubled. CPU is 40%, EBS throughput is at its configured ceiling, and disk queue length rose. What are your options?','The worker reads large sequential files from one gp3 volume.',['The workload can be benchmarked with a representative dataset.'], 'Confirm the volume throughput and instance aggregate EBS limit, then inspect I/O size, filesystem, queue depth and per-process reads. Options include provision more gp3 throughput if only the volume cap binds, use a larger instance if aggregate EBS bandwidth binds, parallelize or cache data if workload allows, or split independent data across volumes. Compare cost and p99 job completion after each change. Avoid changing IOPS if throughput is the measured ceiling.','The saturated resource is throughput, so the remedy must raise or reduce byte demand at that layer.',['Identifies throughput ceiling','Separates volume from instance cap','Tests parallelism/cache and cost'],'Increasing IOPS when the provisioned bytes-per-second limit is already saturated.',3,'Numerical engineering'),
q('ec2-troubleshooting','Scale-out then database failure','After ASG scales from 10 to 40 instances, DB connections quadruple and errors rise. How do you stabilize without hiding the capacity problem?','Each instance opens a 30-connection pool, but normally uses only part of it.',['Other services also use the database.'], 'Immediately bound new connection creation and consider reducing ASG or application pool limits while preserving safe API capacity. Calculate theoretical pool maximum (40 × 30 = 1,200), then measure actual active/idle connections and DB useful limit. Add connection reuse/proxy if compatible, tune worker admission, and move noninteractive work to a queue if its contract allows. Watch pool wait, query latency, error rate and queue age during staged recovery. Do not simply raise the DB max without checking memory and query throughput.','Instance count multiplies connection-pool ceilings even if average CPU is low.',['Calculates 1,200 maximum sessions','Bounds admission and pool behavior','Measures database resource limits and SLO impact'],'Increasing ASG max and database connection max together without load testing.',5,'Progressive interviewer pressure'),
q('ec2-troubleshooting','Boot and health churn','An ASG launches an instance, ALB marks it unhealthy, then the group terminates it and repeats. What loop could cause this and how do you break it safely?','The health grace period is 30 seconds; startup takes about 75 seconds.',['The application eventually becomes healthy if allowed to finish initialization.'], 'The grace period is shorter than measured startup, so the ASG may replace a valid slow starter; repeated boot work can increase package-service or database pressure. Pause or reduce rollout carefully, inspect activity history and target-health reason codes, then set grace/warmup from measured startup and add a readiness probe. Ensure a permanently broken image still fails within a bounded interval. Launch a canary manually or in a test group before allowing fleet replacement to resume.','A too-short health grace can create a self-amplifying replacement loop.',['Identifies timer mismatch','Uses logs and health reason codes','Balances slow start with bounded failure detection'],'Removing health checks entirely to stop the replacement loop.',4,'Production debugging'),
q('ec2-troubleshooting','Security group change evidence','A deployment reports connection timeout after a security-group change. What evidence distinguishes SG, NACL, route and process faults?','Client and target are in different subnets of one VPC.',['VPC Flow Logs are available or can be enabled.'], 'Check route tables for the forward and return path; compare source/destination security groups and port; inspect subnet NACL ingress and egress rules including ephemeral ports; review Flow Logs accept/reject records; then test whether the target process listens on the expected address and port. A timeout suggests packets are dropped or no reply returns, while a refusal often means the host answered but no listener accepted. Restore only the missing narrow rule, then test both directions.','Network-layer failure evidence localizes the path; the application listener is the final gate.',['Orders route, SG, NACL and process checks','Uses logs and timeout/refusal distinction','Applies least-open rule'],'Opening all inbound ports because the error says timeout.',4,'Production debugging'),
];

const lessonById=new Map(expandedLessons.map(lesson=>[lesson.id,lesson]));
export const ec2AuthoredQuestions:InterviewQuestion[]=drafts.map((d,index)=>{
  const number=index+1, next=number===55?1:number+1, harder=number>53?((number+1)%55)+1:number+2;
  const lesson=lessonById.get(d.lesson)!;
  return {id:`U02-Q${String(number).padStart(3,'0')}`,lesson:d.lesson,unit:'02',topic:d.topic,
    difficulty:d.level===1?'Foundation':d.level===5?'Defense':'Applied',difficultyLevel:d.level,
    mode:d.kind==='Production debugging'?'Debugging':d.kind==='Explain the internals'?'Deep dive':'Decision',assessmentType:d.kind,
    prompt:d.prompt,scenario:d.scenario,assumptions:d.assumptions,answer:d.answer,
    explanation:`${d.hinge} ${d.mistake} Interview mein pehle evidence, phir mitigation, phir validation order mein batao.`,
    learningObjective:`Defend ${d.topic} using the stated workload and failure boundary.`,
    rubric:d.rubric,mistakes:[d.mistake,'State what evidence would change the recommendation.'],
    hint:`Trace the request through ${d.topic} and name the observable boundary.`,
    followUp:'What would you measure during a canary or failure drill to prove the fix?',sources:lesson.sources,
    concepts:[d.topic,'Amazon EC2',d.kind],followUps:[`U02-Q${String(next).padStart(3,'0')}`,`U02-Q${String(harder).padStart(3,'0')}`],
    prerequisites:[lesson.prerequisite],revisionNotes:[d.lesson]};
});
